    if (text == null || text.isBlank()) {
        return null;
    }
    try {
        return Instant.parse(text.trim());
    } catch (Exception ex) {
        throw ApiException.unprocessable(fieldName + "格式非法，须为 ISO-8601 UTC 时刻: " + text);
    }
}

